// === SETTINGS ===
const ADMIN_CHAT_ID = 'ADMIN_CHAT_ID'; // <-- замените

// === INPUT ===
const msg = $json.body?.message || {};
const chatId = String(msg.chat?.id || '');
const text = (msg.text || '').trim();
const from = msg.from || {};
const userName = [from.first_name||'', from.last_name||''].join(' ').trim() || (from.username ? '@'+from.username : '');
const isAdmin = (chatId === String(ADMIN_CHAT_ID));

// === MEMORY (workflow static) ===
const store = this.getWorkflowStaticData('global');
store.sessions = store.sessions || {}; // per chat
store.orders = store.orders || [];     // array
const sess = store.sessions[chatId] || { stage: 'idle', client_name:'', client_contact:'', need_type:'', need_text:'' };
const saveSess = () => { store.sessions[chatId] = sess; };

// === OUTPUT HELPERS ===
const items = [];
const pushUser = (text)=> items.push({ json: { mode: 'plain', chatId, text } });
const pushAdmin = (text)=> items.push({ json: { mode: 'plain', chatId: String(ADMIN_CHAT_ID), text } });
const pushAI = (prompt, sys)=> items.push({ json: { mode: 'ai', chatId, prompt, system: sys } });

// === COMMANDS ===
if (text === '/start') {
  sess.stage = 'idle'; sess.client_name = userName; saveSess();
  pushUser('Привет! Я помогу оформить заказ на ИИ-агента или аналитику.\nНапишите /order или просто: "Сделать заказ".');
  return items;
}

if (text === '/report') {
  if (!isAdmin) { pushUser('Команда недоступна.'); return items; }
  const rows = [...store.orders].slice(-10).reverse();
  if (!rows.length) { pushAdmin('Пока без заявок.'); return items; }
  const lines = rows.map(r => `#${r.order_id} | ${r.need_type} | ${r.client_contact} | ${r.ts.slice(0,16).replace('T',' ')}`);
  pushAdmin('Последние заявки:\n' + lines.join('\n'));
  return items;
}

if (text === '/order' || text.toLowerCase() === 'сделать заказ') {
  sess.stage = 'contact'; sess.client_name = userName; saveSess();
  pushUser('Шаг 1/3. Как к вам обращаться и контакт (телефон/Telegram/@)?');
  return items;
}

// === FSM ===
switch (sess.stage) {
  case 'contact': {
    if (text.length < 5) { pushUser('Пожалуйста, укажите имя и контакт (минимум 5 символов).'); return items; }
    sess.client_contact = text; sess.stage = 'need_type'; saveSess();
    pushUser('Шаг 2/3. Что нужно: Агент продаж / Поддержка / Бухгалтер / Аналитика? Можно выбрать и дописать своими словами.');
    return items;
  }
  case 'need_type': {
    const t = text.toLowerCase();
    if (t.includes('продаж')) sess.need_type = 'Агент продаж';
    else if (t.includes('поддерж')) sess.need_type = 'Поддержка';
    else if (t.includes('бух')) sess.need_type = 'Бухгалтер';
    else if (t.includes('аналит')) sess.need_type = 'Аналитика';
    else sess.need_type = text; // свободный ввод
    sess.stage = 'need_text'; saveSess();
    pushUser('Шаг 3/3. Опишите задачу в 1–2 предложениях (что должно делать решение).');
    return items;
  }
  case 'need_text': {
    if (text.length < 5) { pushUser('Добавьте чуть подробностей (минимум 5 символов).'); return items; }
    sess.need_text = text; sess.stage = 'confirm'; saveSess();
    pushUser('Проверьте данные:\n' + `Контакт: ${sess.client_contact}\n` + `Задача: ${sess.need_type} — ${sess.need_text}\n` + 'Если всё верно — напишите: **ПОДТВЕРЖДАЮ**. Если нужно исправить — пришлите правку.');
    return items;
  }
  case 'confirm': {
    if (text.toLowerCase() === 'подтверждаю') {
      const id = 'ORD-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
      const order = { order_id: id, chat_id: chatId, client_name: sess.client_name, client_contact: sess.client_contact, need_type: sess.need_type, need_text: sess.need_text, ts: new Date().toISOString() };
      store.orders.push(order);
      pushUser(`Готово! Заказ №${id} принят. Менеджер свяжется в ближайшее время.`);
      pushAdmin(`🔔 НОВЫЙ ЗАКАЗ\nID: ${order.order_id}\nКонтакт: ${order.client_contact}\nЗадача: ${order.need_type} — ${order.need_text}\nВремя: ${order.ts}`);
      store.sessions[chatId] = { stage:'idle', client_name:'', client_contact:'', need_type:'', need_text:'' };
      return items;
    }
    // правка → назад на need_text
    sess.stage = 'need_text'; saveSess();
    pushUser('Приняла правку. Напишите окончательный вариант задачи (1–2 предложения).');
    return items;
  }
}

// === FALLBACK TO AI ===
// Если мы не в процессе заказа: отвечаем через AI-агента с контекстом
const sys = 'Ты — вежливый и деловой ассистент по внедрению ИИ-агентов и аналитики. Отвечай кратко, по делу, предлагай оформить заказ командой /order, если есть явный запрос. Избегай обещаний, если не уверена. Тон дружелюбный, профессиональный.';
const ctx = `Контекст: стадия=${sess.stage}; контакт=${sess.client_contact||'-'}; выбранное=${sess.need_type||'-'}; описание=${sess.need_text||'-'}`;
const prompt = `${ctx}\n\nСообщение пользователя: ${text}`;
pushAI(prompt, sys);
return items;
